export interface Cursor {
  ts: number;
  id: string;
}

/**
 * Encode a page boundary as an opaque string.
 *
 * `ts` alone is not enough: two rows can share a millisecond, and a cursor that cannot
 * break that tie either repeats one of them or skips it. The id is the tiebreak.
 */
export function encodeCursor(cursor: Cursor): string {
  return Buffer.from(`${cursor.ts}:${cursor.id}`, "utf8").toString("base64url");
}

/** Decode a cursor, or null for anything this build did not write. */
export function decodeCursor(raw: string): Cursor | null {
  let decoded: string;
  try {
    decoded = Buffer.from(raw, "base64url").toString("utf8");
  } catch {
    return null;
  }
  const split = decoded.indexOf(":");
  if (split <= 0) return null;
  const ts = Number(decoded.slice(0, split));
  const id = decoded.slice(split + 1);
  if (!Number.isSafeInteger(ts) || !id) return null;
  return { ts, id };
}

import { type Cursor, encodeCursor } from "./cursor.ts";

export interface FleetCounts {
  active: number;
  waiting: number;
  idle: number;
}

export interface HistoryPage {
  counts: FleetCounts[];
  nextCursor: string | null;
}

/** A one-line summary of the fleet's current state. */
export function summarize(counts: FleetCounts): string {
  return `${counts.active} active, ${counts.waiting} waiting, ${counts.idle} idle`;
}

/**
 * One page of summary history, bounded by a keyed cursor rather than an offset.
 *
 * `nextCursor` is null on the last page, which is what lets a caller stop without a second
 * round trip that returns nothing.
 */
export function historyPage(rows: Array<FleetCounts & Cursor>, limit: number): HistoryPage {
  const page = rows.slice(0, limit);
  const last = page.at(-1);
  return {
    counts: page.map(({ active, waiting, idle }) => ({ active, waiting, idle })),
    nextCursor: rows.length > limit && last ? encodeCursor({ ts: last.ts, id: last.id }) : null,
  };
}
